const today = DateTime.now().toFormat('yyyy-MM-dd');
return $input.all().map(item => {
  const i = item.json;
  const allFixtures = i.data || [];
  const todayFixtures = allFixtures.filter(f => {
    const d = f.fixture?.start_date || f.start_date || '';
    return d.startsWith(today);
  });
  return {
    json: {
      ...i,
      data: todayFixtures,
      hasMatch: todayFixtures.length > 0,
      debugCount: allFixtures.length,
      debugFirstDate: allFixtures[0]?.fixture?.start_date || allFixtures[0]?.start_date || 'NO_DATE'
    }
  };
});

return $input.all().map(item => {
  const { data: fixturesData, debugCount, debugFirstDate, hasMatch, ...teamInfo } = item.json;
  const fixture = (fixturesData || [])[0];
  if (!fixture) return { json: { ...teamInfo, skip: true } };
  const f = fixture.fixture || {};
  const homeId = f.home_competitors?.[0]?.id;
  const isHome = homeId === teamInfo.opticoddsId;
  const homeScore = fixture.scores?.home?.total ?? 0;
  const awayScore = fixture.scores?.away?.total ?? 0;
  const goalsFor     = isHome ? homeScore : awayScore;
  const goalsAgainst = isHome ? awayScore : homeScore;
  const opponentName = isHome
    ? (f.away_team_display || f.away_competitors?.[0]?.name || 'Unknown')
    : (f.home_team_display || f.home_competitors?.[0]?.name || 'Unknown');
  const opponentId = isHome ? f.away_competitors?.[0]?.id : f.home_competitors?.[0]?.id;
  const events   = fixture.events || [];
  const myStats  = ((isHome ? fixture.stats?.home : fixture.stats?.away) || []).find(s => s.period === 'all')?.stats || {};
  const oppStats = ((isHome ? fixture.stats?.away : fixture.stats?.home) || []).find(s => s.period === 'all')?.stats || {};
  const competition = fixture.league?.name || fixture.league?.id || '';
  return {
    json: {
      ...teamInfo,
      teamId: teamInfo.opticoddsId,
      opponentName, opponentId, isHome,
      goalsFor, goalsAgainst,
      matchId: f.id, matchDate: f.start_date,
      competition, events, myStats, oppStats
    }
  };
});

return $input.all().map(item => {
  const { data: nextFixturesRaw, ...matchData } = item.json;
  const nextFixtures = nextFixturesRaw || [];
  let nextOpponent = 'TBD', nextMatchDate = null, nextCompetition = 'TBD';
  if (nextFixtures[0]) {
    const nf = nextFixtures[0].fixture || {};
    const homeId = nf.home_competitors?.[0]?.id;
    const isHome = homeId === matchData.teamId;
    nextOpponent = isHome
      ? (nf.away_team_display || nf.away_competitors?.[0]?.name || 'TBD')
      : (nf.home_team_display || nf.home_competitors?.[0]?.name || 'TBD');
    nextMatchDate = nf.start_date;
    nextCompetition = nextFixtures[0].league?.name || 'TBD';
  }
  return { json: { ...matchData, nextOpponent, nextMatchDate, nextCompetition } };
});

return $input.all().map(item => {
  const { data: injuriesRaw, ...d } = item.json;
  const injuries = (injuriesRaw || [])
    .filter(inj => inj.player?.name)
    .slice(0, 5)
    .map(inj => ({ name: inj.player.name, position: inj.player.position || '', status: inj.status, type: inj.type }));
  const goalEvents = (d.events || []).filter(e => {
    const t = (e.type || e.event_type || '').toLowerCase();
    return t.includes('goal') && (e.team_id === d.teamId || e.competitor_id === d.teamId);
  });
  const goalScorers = goalEvents.map(e => e.player_name || e.player?.name).filter(Boolean);
  const result = d.goalsFor > d.goalsAgainst ? 'WIN' : d.goalsFor < d.goalsAgainst ? 'LOSS' : 'DRAW';
  return { json: { ...d, result, injuries, goalScorers } };
});

return $input.all().map(item => {
  const d = item.json;
  let nextFixtureText = 'No upcoming match currently scheduled.';
  if (d.nextMatchDate) {
    const dt = new Date(d.nextMatchDate);
    const formatted = dt.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
    nextFixtureText = 'Next: ' + d.nextOpponent + ' (' + d.nextCompetition + ') - ' + formatted;
  }
  const lines = [
    'Update the website for ' + d.teamName + '.',
    '',
    'MATCH:',
    '- ' + d.competition + ' | ' + (d.isHome ? 'Home' : 'Away') + ' vs ' + d.opponentName,
    '- Result: ' + d.result + ' ' + d.goalsFor + '-' + d.goalsAgainst
  ];
  if (d.goalScorers && d.goalScorers.length > 0) lines.push('- Goals: ' + d.goalScorers.join(', '));
  if (d.myStats && Object.keys(d.myStats).length > 0) {
    const s = d.myStats;
    const parts = [];
    const shots = s.total_scoring_att ?? s.shots;
    const onTarget = s.ontarget_scoring_att ?? s.shots_on_target;
    if (shots !== undefined) parts.push('Shots ' + shots + (onTarget !== undefined ? ' (' + onTarget + ' on target)' : ''));
    const poss = s.possession_percentage ?? s.possession;
    if (poss !== undefined) parts.push('Possession ' + poss + '%');
    const corners = s.corner_taken ?? s.corners;
    if (corners !== undefined) parts.push('Corners ' + corners);
    if (parts.length > 0) lines.push('- Stats: ' + parts.join(' | '));
  }
  lines.push('', 'NEXT MATCH: ' + nextFixtureText);
  if (d.injuries && d.injuries.length > 0) {
    lines.push('', 'INJURY LIST:');
    d.injuries.forEach(inj => lines.push('- ' + inj.name + (inj.position ? ' (' + inj.position + ')' : '') + ': ' + inj.status + ' - ' + inj.type));
  }
  lines.push('', "Write a punchy, supporter-facing 2-3 sentence update for the team's website. Requirements:", '1. Open with the result and score - mention the scorer(s) if available', '2. Include a performance detail from the stats if provided', '3. Close with the next fixture', '4. If there are injuries, weave in one concern naturally', '', 'Return ONLY plain text - no HTML, no markdown, no quotes.');
  const prompt = lines.join('\n');
  const claudeBody = { model: 'claude-sonnet-4-6', max_tokens: 300, messages: [{ role: 'user', content: prompt }] };
  return { json: { ...d, prompt, claudeBody } };
});

return $input.all().map(item => {
  const d = item.json;
  const generatedContent = (d.content || [])[0]?.text?.trim() || '';
  if (!generatedContent) throw new Error('Claude returned empty content for ' + d.teamName);
  const resultEmoji = d.result === 'WIN' ? ':white_check_mark:' : d.result === 'LOSS' ? ':x:' : ':heavy_minus_sign:';
  const scoreText = d.goalsFor + '-' + d.goalsAgainst;
  const scorerLine = d.goalScorers?.length > 0 ? 'Goals: ' + d.goalScorers.join(', ') : null;
  const contextParts = [d.competition || 'Premier League'];
  if (d.nextOpponent !== 'TBD') contextParts.push('Next: ' + d.nextOpponent + ' (' + d.nextCompetition + ')');
  if (d.injuries?.length > 0) contextParts.push('Injuries: ' + d.injuries.length);
  const slackBody = {
    text: d.teamName + ' | ' + d.result + ' ' + scoreText + ' vs ' + d.opponentName,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: d.teamName + '  |  ' + d.result + ' ' + scoreText, emoji: true } },
      { type: 'section', text: { type: 'mrkdwn', text: resultEmoji + '  *vs ' + d.opponentName + '*  (' + (d.competition || 'Premier League') + ')' + (scorerLine ? '\n' + scorerLine : '') + '\n\n' + generatedContent } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: contextParts.join('  |  ') }] }
    ]
  };
  return { json: { ...d, generatedContent, slackBody } };
});

return $input.all().map(item => {
  const d = item.json;
  const ts = new Date().toISOString();
  console.log('[' + ts + '] OK | ' + d.teamName + ' | ' + d.result + ' ' + d.goalsFor + '-' + d.goalsAgainst + ' vs ' + d.opponentName);
  return { json: { success: true, timestamp: ts, team: d.teamName, result: d.result + ' ' + d.goalsFor + '-' + d.goalsAgainst, opponent: d.opponentName, competition: d.competition } };
});
